 _amountLP, uint256 _minAmountLD, bytes calldata _to, lzTxObj memory _lzTxParams ) external payable; function instantRedeemLocal( uint16 _srcPoolId, uint256 _amountLP, address _to ) external returns (uint256); function redeemLocal( uint16 _dstChainId, uint256 _srcPoolId, uint256 _dstPoolId, address payable _refundAddress, uint256 _amountLP, bytes calldata _to, lzTxObj memory _lzTxParams ) external payable; function sendCredits( uint16 _dstChainId, uint256 _srcPoolId, uint256 _dstPoolId, address payable _refundAddress ) external payable; function quoteLayerZeroFee( uint16 _dstChainId, uint8 _functionType, bytes calldata _toAddress, bytes calldata _transferAndCallPayload, lzTxObj memory _lzTxParams ) external view returns (uint256, uint256); } library SafeApprove { error ErrApproveFailed(); error ErrApproveFailedWithData(bytes data); function safeApprove( IERC20 token, address to, uint256 value ) internal { (bool success, bytes memory data) = address(token).call(abi.encodeCall(IERC20.approve, (to, value))); if (!success) { revert ErrApproveFailed(); } if (data.length != 0 && !abi.decode(data, (bool))) { revert ErrApproveFailedWithData(data); } } } contract ZeroXStargateLPSwapper is ISwapperV2 { using BoringERC20 for IERC20; using SafeApprove for IERC20; error ErrSwapFailed(); IBentoBoxV1 public immutable bentoBox; IStargatePool public immutable pool; IERC20 public immutable mim; IERC20 public immutable underlyingToken; IStargateRouter public immutable stargateRouter; address public immutable zeroXExchangeProxy; uint16 public immutable poolId; constructor( IBentoBoxV1 _bentoBox, IStargatePool _pool, uint16 _poolId, IStargateRouter _stargateRouter, IERC20 _mim, address _zeroXExchangeProxy ) { bentoBox = _bentoBox; pool = _pool; poolId = _poolId; mim = _mim; stargateRouter = _stargateRouter; zeroXExchangeProxy = _zeroXExchangeProxy; underlyingToken = IERC20(_pool.token()); underlyingToken.safeApprove(_zeroXExchangeProxy, type(uint256).max); mim.approve(address(_bentoBox), type(uint256).max); } function swap( address, address, address recipient, uint256 shareToMin, uint256 shareFrom, bytes calldata swapData ) public override returns (uint256 extraShare, uint256 shareReturned) { bentoBox.withdraw(IERC20(address(pool)), address(this), address(this), 0, shareFrom); uint256 amount = IERC20(address(pool)).balanceOf(address(this)); stargateRouter.instantRedeemLocal(poolId, amount, address(this)); require(IERC20(address(pool)).balanceOf(address(this)) == 0, "Cannot fully redeem"); (bool success, ) = zeroXExchangeProxy.call(swapData); if (!success) { revert ErrSwapFailed(); } (, shareReturned) = bentoBox.deposit(mim, address(this), recipient, mim.balanceOf(address(this)), 0); extraShare = shareReturned - shareToMin; } }

